// Lineare Suche. Bei ~1000 Tokens und kurzen Prompts ist das
// auf dem ESP32 unkritisch; falls es stoert, ist das Vokabular
// sortiert (nach den Sondertokens) und binaer durchsuchbar.
static inline int llm_token_to_id(const char* token)
{
    for (int i = 0; i < LLM_VOCAB_SIZE; ++i) {
        const char* p = llm_itos[i];
        int j = 0;
        while (token[j] && p[j] && token[j] == p[j]) { ++j; }
        if (!token[j] && !p[j]) { return i; }
    }
    return LLM_UNK_ID;
}
